"import json\nimport os\n\npath = r\"C:\\Users\\a-6600\\.gemini\\antigravity\\brain\\defefd3d-03a6-48cc-ab0b-1fbc66f83de5\\.system_generated\\logs\\transcript.jsonl\"\nwith open(path, \"r\", encoding=\"utf-8\") as f:\n    for idx, line in enumerate(f):\n        if \"fin_customers\" in line and \"CREATE TABLE\" in line:\n            obj = json.loads(line)\n            # Search for any content or tool args\n            print(f\"Line {idx} matches criteria!\")\n            content = obj.get(\"content\", \"\")\n            if \"CREATE TABLE\" in content:\n                print(f\"  Found in content of line {idx}. Size: {len(content)}\")\n                with open(f\"extracted_sql_{idx}.sql\", \"w\", encoding=\"utf-8\") as outf:\n                    outf.write(content)\n            for tc in obj.get(\"tool_calls\", []):\n                args = tc.get(\"args\", {})\n                code = args.get(\"CodeContent\") or args.get(\"ReplacementContent\")\n                if code and \"CREATE TABLE\" in code:\n                    print(f\"  Found in tool call code of line {idx}. Size: {len(code)}\")\n                    with open(f\"extracted_sql_{idx}.sql\", \"w\", encoding=\"utf-8\") as outf:\n                        outf.write(code)\n"